        color: var(--muted);
        font-size: 1.06rem;
        line-height: 1.6;
      }

      .faq {
        display: grid;
        gap: 14px;
        padding: 8px;
      }

      .example {
        background: var(--panel);
        border: 1px solid var(--panel-border);
        border-radius: var(--radius);
        box-shadow: var(--shadow);
        backdrop-filter: blur(16px);
        overflow: clip;
