  <body>
    <main class="page">
      <div class="shell">
        <header class="hero">
          <span class="eyebrow">Cats 101</span>
          <h1>Frequently asked cat questions</h1>
          <p class="lead">
            A concise FAQ for curious humans who want the essentials on cat behavior, care, and why
            the box is always the best seat in the house.
          </p>
        </header>

        <section id="faq" class="faq" aria-label="Cat frequently asked questions"></section>
      </div>
    </main>

    <script>
      const faqs = [
        {
          question: "Why do cats knead with their paws?",
          answer:
            "Kneading is a comforting, instinctive behavior that often shows contentment. Cats may do it when they are relaxed, sleepy, or feeling especially safe."
        },
        {
          question: "Why do cats love boxes so much?",
          answer:
            "Boxes feel secure, warm, and enclosed. They give cats a cozy place to hide, observe their surroundings, and reduce stress."
        },
        {
          question: "How much sleep do cats need?",
          answer:
            "Most cats sleep between 12 and 16 hours a day, and some even more. Their energy tends to come in bursts, especially around dawn and dusk."
        },
        {
          question: "Do indoor cats still need enrichment?",
          answer:
            "Yes. Scratching posts, puzzle feeders, climbing spots, and regular play help indoor cats stay mentally and physically active."
        },
        {
          question: "Why do cats purr?",
          answer:
            "Purring can signal relaxation, but cats also purr when they are nervous, hurt, or trying to self-soothe. The sound can mean several things depending on context."
        }
      ];

      function Chevron() {
        return `
          <svg class="chevron" viewBox="0 0 24 24" aria-hidden="true" fill="none">
            <path d="M6 9l6 6 6-6" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" />
          </svg>
        `;
      }

      function FaqItem({ question, answer }, index) {
        const buttonId = `faq-button-${index}`;
        const panelId = `faq-panel-${index}`;

        return `
          <div class="example" data-open="false">
            <button
              class="question"
              id="${buttonId}"
              type="button"
              aria-expanded="false"
              aria-controls="${panelId}"
            >
              <span class="question-text">${question}</span>
              ${Chevron()}
            </button>
            <div class="details" id="${panelId}" role="region" aria-labelledby="${buttonId}" hidden>
              <p>${answer}</p>
            </div>
          </div>
        `;
      }

      function FaqApp(items) {
        return items.map(FaqItem).join("");
      }

      const faqRoot = document.getElementById("faq");
      faqRoot.innerHTML = FaqApp(faqs);

      faqRoot.addEventListener("click", (event) => {
        const button = event.target.closest(".question");
        if (!button) return;

        const card = button.closest(".example");
        const panel = document.getElementById(button.getAttribute("aria-controls"));
        const isOpen = button.getAttribute("aria-expanded") === "true";

        button.setAttribute("aria-expanded", String(!isOpen));
        card.dataset.open = String(!isOpen);
        panel.hidden = isOpen;
      });
    </script>
